  /**
   * Method under test: {@link ProtoRuleProtos.ProtoRule#parseFrom(InputStream)}
   */
  @Test
  void testProtoRuleParseFrom10() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class, () -> ProtoRuleProtos.ProtoRule.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

  /**
   * Method under test: {@link ProtoRuleProtos.ProtoRule#parseFrom(InputStream)}
   */
  @Test
  void testProtoRuleParseFrom11() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt()))
        .thenThrow(new InvalidProtocolBufferException("The characteristics of someone or something"));

    // Act and Assert
    assertThrows(InvalidProtocolBufferException.class, () -> ProtoRuleProtos.ProtoRule.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

